{"content": "// Known id store: each known id maps to a value.
const KNOWN = new Map([
  ['a', 'alpha'],
  ['b', 'bravo'],
  ['c', 'charlie'],
]);

function isNonEmptyStringArray(ids) {
  return Array.isArray(ids) && ids.length > 0 && ids.every((id) => typeof id === 'string');
}

function rejectExtraArgs(args, allowed) {
  const keys = Object.keys(args);
  if (keys.some((k) => !allowed.includes(k))) {
    throw new Error('Invalid arguments: unexpected argument');
  }
}

export async function listTools() {
  return [
    {
      name: 'batch_lookup',
      description: 'Look up multiple ids in one batch. Returns one result per id in input order; missing ids are reported individually without aborting the batch.',
      inputSchema: {
        type: 'object',
        properties: {
          ids: {
            type: 'array',
            items: { type: 'string' },
            description: 'Non-empty array of id strings to look up.',
          },
        },
        required: ['ids'],
        additionalProperties: false,
      },
    },
  ];
}

export async function callTool(name, args = {}) {
  if (name !== 'batch_lookup') {
    throw new Error(`Unknown tool: ${name}`);
  }

  // Reject extra/invalid arguments.
  rejectExtraArgs(args, ['ids']);

  if (!('ids' in args)) {
    throw new Error("Missing required argument: 'ids'");
  }
  if (!isNonEmptyStringArray(args.ids)) {
    throw new Error("'ids' must be a non-empty array of strings");
  }

  const results = args.ids.map((id) => {
    if (KNOWN.has(id)) {
      return { id, ok: true, value: KNOWN.get(id) };
    }
    return { id, ok: false, error: `id not found: ${id}` };
  });

  return {
    content: [
      {
        type: 'text',
        text: JSON.stringify({ results }),
      },
    ],
  };
}
