try { await callTool('batch_lookup', { ids: ['a', 5] }); console.log('FAIL: should have thrown'); }
catch (e) { console.log('OK non-string ids rejected:', e.message); }

// order + partial
const r = JSON.parse((await callTool('batch_lookup', { ids: ['x', 'a', 'z', 'b'] })).content[0].text);
console.log('OK results:', JSON.stringify(r.results.map(x => [x.id, x.ok])));

// listTools schema
const tools = await listTools();
console.log('OK schema additionalProperties:', tools[0].inputSchema.additionalProperties);
